import{U as e,W as t,nt as n,t as r}from"./chunks/framework.CPHJXLir.js";var i=JSON.parse(`{"title":"Event-Driven Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"events/event-driven-architecture.md","filePath":"events/event-driven-architecture.md"}`),a={name:`events/event-driven-architecture.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="event-driven-architecture" tabindex="-1">Event-Driven Architecture <a class="header-anchor" href="#event-driven-architecture" aria-label="Permalink to “Event-Driven Architecture”">​</a></h1><p>Event-driven architecture (EDA) is a software design approach where different parts of an application communicate by <strong>producing and responding to events</strong>.</p><p>An <strong>event</strong> is a notification that something has happened in the application.</p><p>For example, in Business Central:</p><ul><li>A sales order is released.</li><li>A customer record is created.</li><li>An invoice is posted.</li></ul><p>Other parts of the application can respond to these events without needing to be directly called by the code that produced them.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to “How It Works”">​</a></h2><p>EDA involves three main concepts:</p><ol><li><strong>Event Publisher:</strong> The component that raises or announces an event.</li><li><strong>Event:</strong> The notification that something has happened.</li><li><strong>Event Subscriber:</strong> The component that listens for an event and executes code when it occurs.</li></ol><h3 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h3><p>Imagine a customer record is created in Business Central.</p><ul><li>The customer creation process raises an event.</li><li>A subscriber listens for that event.</li><li>When the event occurs, the subscriber executes additional logic, such as sending a notification.</li></ul><p>The original customer creation process doesn&#39;t need to know about the subscriber.</p><h2 id="why-use-event-driven-architecture" tabindex="-1">Why Use Event-Driven Architecture? <a class="header-anchor" href="#why-use-event-driven-architecture" aria-label="Permalink to “Why Use Event-Driven Architecture?”">​</a></h2><ul><li><strong>Loose coupling:</strong> Components can communicate without depending directly on one another.</li><li><strong>Extensibility:</strong> Developers can add functionality without modifying existing application code.</li><li><strong>Maintainability:</strong> Changes to one component are less likely to affect others.</li><li><strong>Reusability:</strong> Multiple subscribers can respond to the same event.</li></ul><h2 id="key-takeaway" tabindex="-1">Key Takeaway <a class="header-anchor" href="#key-takeaway" aria-label="Permalink to “Key Takeaway”">​</a></h2><p>In Business Central, event-driven architecture allows extensions to respond to application events and introduce additional functionality without unnecessarily modifying Microsoft&#39;s base application.</p><p>This makes applications easier to extend, maintain and upgrade.</p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};